local function slice(p1, p2, p3) -- line: 2
    local v1, v2 = utf8.len(p1)

    assert(v1 ~= nil, ("string `%s` has an invalid byte at position %s"):format(p1, (tostring(v2))))

    local v5 = tonumber(p2)

    assert(typeof(v5) == "number", "startIndexStr should be a number")

    if v5 + v1 < 0 then
        v5 = 1
    end

    if v1 < v5 then
        return ""
    end

    local v7 = v1 + 1

    if p3 ~= nil then
        v7 = tonumber(p3) or (0/0)
    end

    assert(typeof(v7) == "number", "lastIndexStr should convert to number")

    if v1 < v7 then
        v7 = v1 + 1
    end

    return (string.sub(p1, utf8.offset(p1, v5), utf8.offset(p1, v7) - 1))
end

return slice
